interface Trampoline<T> {
    T get();
    default boolean complete() { return true; }
    default Trampoline<T> jump() { return this; }
}
static <T> Trampoline<T> done(T v) { return () -> v; }
static <T> Trampoline<T> more(Supplier<Trampoline<T>> next) {
    return new Trampoline<T>() {
        public boolean complete() { return false; }
        public Trampoline<T> jump() { return next.get(); }
        public T get() { return next.get().get(); }
    };
}
static <T> T run(Trampoline<T> t) { while (!t.complete()) t = t.jump(); return t.get(); }
